<script setup lang="ts">import{computed,provide,shallowRef}from"vue";import{useRoute}from"vue-router";import AppSidebar from"../components/layout/AppSidebar.vue";import AppTopbar from"../components/layout/AppTopbar.vue";import ContextRail from"../components/layout/ContextRail.vue";import GlobalSearchDialog from"../components/layout/GlobalSearchDialog.vue";import MobileNavigation from"../components/layout/MobileNavigation.vue";const collapsed=shallowRef(false);const searchOpen=shallowRef(false);const mobileOpen=shallowRef(false);const railOpen=shallowRef(false);const route=useRoute();const hasContextRail=computed(()=>Boolean(route.meta.feature?.requiresContextRail));const openSearch=()=>{searchOpen.value=true};provide<() => void>("openSearch",openSearch);</script><template><a class="skip-link" href="#main-content">跳到主要内容</a><div class="shell" :class="{ 'with-context-rail': hasContextRail }"><AppSidebar :collapsed="collapsed" @toggle="collapsed=!collapsed"/><div class="work"><AppTopbar @open-search="openSearch" @open-menu="mobileOpen=true"/><main id="main-content" class="content" tabindex="-1"><RouterView v-slot="{ Component }"><Transition name="page" mode="out-in"><component :is="Component"/></Transition></RouterView></main></div><ContextRail :open="railOpen" @close="railOpen=false"/><MobileNavigation :open="mobileOpen" @close="mobileOpen=false"/><GlobalSearchDialog v-model="searchOpen"/></div></template><style scoped>.skip-link{position:fixed;z-index:100;top:.5rem;left:.5rem;transform:translateY(-200%);padding:.65rem .8rem;border-radius:6px;background:var(--color-primary);color:#fff;font-weight:800;text-decoration:none}.skip-link:focus{transform:translateY(0)}.shell{display:grid;grid-template-columns:auto minmax(0,1fr);min-height:100vh;background:var(--page-bg)}.shell.with-context-rail{grid-template-columns:auto minmax(0,1fr) var(--rail)}.work{min-width:0}.content{min-height:calc(100vh - 65px)}.page-enter-active,.page-leave-active{transition:opacity .18s ease,transform .18s ease}.page-enter-from{opacity:0;transform:translateY(8px)}.page-leave-to{opacity:0;transform:translateY(-4px)}@media(max-width:1100px){.shell.with-context-rail{grid-template-columns:auto minmax(0,1fr)}}@media(max-width:900px){.shell{display:block}.shell>:first-child{display:none}}</style>
